    "ixs.archLabel": "सुरक्षा ढाँचा",
    "ixs.requestDocs": "सुरक्षा दस्तावेज़ माँगें",
    "ixs.confScope": "संविदात्मक",
    "ixs.note": "सांकेतिक रूपरेखा। \"संरेखित\" इंजीनियरिंग इरादे का संकेत है, न कि वर्तमान तृतीय-पक्ष प्रत्यायन का। Mizan कानूनी फर्म नहीं है; कानूनी सलाह केवल अलग से संविदात्मक रूप से नियोजित होने पर ही दी जाती है।",
    "fq.badge": "प्रश्नोत्तर",
    "fq.title": "प्रश्न, उत्तर दिए गए",
    "fq.sub": "Mizan कैसे जुड़ता है, क्या देता है और आपकी जानकारी कैसे सुरक्षित रहती है — इससे जुड़े सामान्य प्रश्न।",
    "fq.1q": "Mizan वास्तव में क्या करता है?",
    "fq.1a": "Mizan वित्तीय विश्लेषण, कानूनी खुफिया, नियामक निगरानी और जोखिम मूल्यांकन को संरचित सहभागिताओं में जोड़ता है। हर सहभागिता प्रलेखित अनुशंसाओं और एक स्पष्ट निर्णय पथ के साथ समाप्त होती है।",
    "fq.2q": "क्या Mizan कानूनी फर्म या वित्तीय संस्थान है?",
    "fq.2a": "नहीं। Mizan एक परामर्श-और-खुफिया प्लेटफ़ॉर्म है। यह कानूनी फर्म नहीं है और ग्राहक निधि रखता नहीं है। योग्य सलाह केवल अलग से संविदात्मक रूप से नियोजित होने पर ही दी जाती है।",
    "fq.3q": "मेरी जानकारी कैसे सुरक्षित रहती है?",
    "fq.3a": "सहभागिताएँ गोपनीयता से शुरू होती हैं। कार्य निष्पादन परिवहन एवं भंडारण में एन्क्रिप्टेड होता है, पहुँच सहभागिता के अनुसार स्कोप की जाती है, और रिकॉर्ड बताई गई, ग्राहक-दृश्यमान नीतियों के तहत रखे जाते हैं।",
    "fq.4q": "आप किन क्षेत्राधिकारों को कवर करते हैं?",
    "fq.4a": "कवरेज प्रमुख वित्तीय केंद्रों और सीमापार गलियारों में फैला है — जिसमें GCC, EU/EEA, UK, US और APAC शामिल हैं। हर सहभागिता से पहले क्षेत्राधिकार-विशिष्ट विश्लेषण की पुष्टि की जाती है।",
    "fq.5q": "सहभागिता कैसे शुरू होती है?",
    "fq.5a": "एक गोपनीय बातचीत से। अनुरोध सबमिट करें, और Mizan टीम कोई कार्य शुरू होने से पहले उद्देश्यों, कवरेज और शर्तों पर सहमति के लिए अनुवर्ती करती है।",
    "tm.badge": "सलाहकार टीम",
    "tm.title": "विश्लेषण के पीछे के दिमाग़",
    "tm.sub": "वैश्विक बाज़ारों में वित्तीय, कानूनी और नियामक अनुभव। प्रोफ़ाइल इस प्रदर्शन के लिए सांकेतिक हैं।",
    "ft.work": "हम कैसे काम करते हैं",
    "footer.tagline": "जटिल वित्तीय और कानूनी निर्णयों के लिए खुफिया। कानूनी फर्म या लाइसेंस प्राप्त वित्तीय संस्थान नहीं।",
