    "ixs.note": "Esquema ilustrativo. «Alineado» se refiere a la intención de ingeniería, no a una certificación actual de terceros. Mizan no es un despacho de abogados; el asesoramiento legal se presta solo cuando se contrata por separado.",
    "fq.badge": "Preguntas frecuentes",
    "fq.title": "Preguntas, respondidas",
    "fq.sub": "Preguntas frecuentes sobre cómo se vincula Mizan, qué entrega y cómo se protege su información.",
    "fq.1q": "¿Qué hace realmente Mizan?",
    "fq.1a": "Mizan combina análisis financiero, inteligencia legal, monitoreo regulatorio y evaluación de riesgos en compromisos estructurados. Cada compromiso termina con recomendaciones documentadas y una ruta de decisión clara.",
    "fq.2q": "¿Es Mizan un despacho de abogados o una institución financiera?",
    "fq.2a": "No. Mizan es una plataforma de asesoría e inteligencia. No es un despacho de abogados ni custodia fondos de clientes. El asesoramiento cualificado se presta solo cuando se contrata por separado.",
    "fq.3q": "¿Cómo se protege mi información?",
    "fq.3a": "Los compromisos comienzan con confidencialidad. El trabajo se cifra en tránsito y en reposo, el acceso se limita a cada compromiso y los registros se retienen según políticas declaradas y visibles para el cliente.",
    "fq.4q": "¿Qué jurisdicciones cubren?",
    "fq.4a": "La cobertura abarca los principales centros financieros y corredores transfronterizos, incluidos el CCG, la UE/EEE, el Reino Unido, EE. UU. y APAC. El análisis específico por jurisdicción se confirma antes de iniciar cada compromiso.",
    "fq.5q": "¿Cómo comienza un compromiso?",
    "fq.5a": "Con una conversación confidencial. Envíe una solicitud y el equipo de Mizan hará seguimiento para acordar objetivos, alcance y términos antes de comenzar cualquier trabajo.",
