    "fq.3q": "كيف تُحمى معلوماتي؟",
    "fq.3a": "الالتزامات تبدأ بالسرية. تُشفَّر مخرجات العمل أثناء النقل وحال السكون، ويحدد الوصول لكل التزام، وتحفظ السجلات وفق سياسات معلنة ومتاحة للعميل.",
    "fq.4q": "ما الولايات القضائية التي تغطونها؟",
    "fq.4a": "التغطية تشمل المراكز المالية الكبرى والممرات عبر الحدود — بما في ذلك دول الخليج والاتحاد الأوروبي/المنطقة الاقتصادية الأوروبية والمملكة المتحدة والولايات المتحدة وآسيا والمحيط الهادئ. يُؤكَّد التحليل الخاص بكل ولاية قبل بدء كل التزام.",
    "fq.5q": "كيف يبدأ التزام؟",
    "fq.5a": "بمحادثة سرية. أرسل طلباً، ويتابع فريق Mizan للاتفاق على الأهداف والتغطية والشروط قبل بدء أي عمل.",
