    "fq.1q": "Mizan اصل میں کیا کرتا ہے؟",
    "fq.1a": "Mizan مالی تجزیہ، قانونی انٹیلیجنس، ریگولیٹری مانیٹرنگ اور رسک اسسمنٹ کو سٹرکچرڈ مصروفیات میں یکجا کرتا ہے۔ ہر مصروفیت دستاویزی سفارشات اور واضح فیصلے کے راستے کے ساتھ ختم ہوتی ہے۔",
